def list_commits(limit=None, author=None, since=None, until=None):
    import json, os, datetime
    path = os.path.join(_DB, 'commits.json')
    try:
        with open(path, 'r', encoding='utf-8') as f:
            commits = json.load(f)
    except FileNotFoundError:
        return []
    def parse_date(d):
        if not d:
            return None
        try:
            return datetime.datetime.fromisoformat(d.replace('Z', '+00:00'))
        except Exception:
            try:
                return datetime.datetime.strptime(d, '%a %b %d %H:%M:%S %Y %z')
            except Exception:
                return None
    filtered = []
    for c in commits:
        if author and c.get('author') != author:
            continue
        commit_date = parse_date(c.get('date'))
        if since:
            since_dt = parse_date(since)
            if since_dt is not None and (not commit_date or commit_date < since_dt):
                continue
        if until:
            until_dt = parse_date(until)
            if until_dt is not None and (not commit_date or commit_date > until_dt):
                continue
        filtered.append(c)
    filtered.sort(key=lambda x: x.get('date', ''), reverse=True)
    if limit is not None:
        filtered = filtered[:limit]
    return filtered

