def list_users(limit=None, cursor=None, username=None, entity=None, created_since=None, created_until=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0391000" if __import__("os").path.isdir("./environment_mix/0391000") else "/app/database")
