        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None, "must be a non-empty RFC3339 date-time string"
        try:
            st = s.strip()
            if st.endswith("Z"):
                st = st[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(st), None
        except ValueError:
            return None, "must be a valid RFC3339 date-time string"

    t0 = time.time()
    endpoint = "list_users"
    status = "success"

    # Validation
    if limit is not None:
        if not isinstance(limit, int):
            status = "error"
            result = _err("VALIDATION_ERROR", "limit must be an integer when provided.")
        elif limit <= 0:
            status = "error"
            result = _err("VALIDATION_ERROR", "limit must be a positive integer when provided.")
        else:
            result = None
    else:
        result = None

    if result is None and cursor is not None and not isinstance(cursor, str):
        status = "error"
        result = _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    if result is None and username is not None:
        if not isinstance(username, str):
            status = "error"
            result = _err("VALIDATION_ERROR", "username must be a string when provided.")
        elif not username.strip():
            status = "error"
            result = _err("VALIDATION_ERROR", "username must not be blank when provided.")

    if result is None and entity is not None:
        if not isinstance(entity, str):
            status = "error"
            result = _err("VALIDATION_ERROR", "entity must be a string when provided.")
        elif not entity.strip():
            status = "error"
            result = _err("VALIDATION_ERROR", "entity must not be blank when provided.")

    if result is None and sort_by is not None and sort_by not in ("created_at", "username"):
        status = "error"
        result = _err("VALIDATION_ERROR", "sort_by must be one of: created_at, username.")
    if result is None and sort_order is not None and sort_order not in ("asc", "desc"):
        status = "error"
        result = _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.")

    cs = cu = None
    if result is None and created_since is not None:
        cs, err = _parse_dt(created_since)
        if err:
            status = "error"
            result = _err("VALIDATION_ERROR", f"created_since {err}.")
    if result is None and created_until is not None:
        cu, err = _parse_dt(created_until)
        if err:
            status = "error"
            result = _err("VALIDATION_ERROR", f"created_until {err}.")
    if result is None and cs is not None and cu is not None and cs > cu:
        status = "error"
        result = _err("VALIDATION_ERROR", "Contradictory date range: created_since is after created_until.")

    users = None
    if result is None:
        users = _load("users.json")
        if isinstance(users, dict) and "rows" in users:
            users = users.get("rows", [])
        if not isinstance(users, list):
            status = "error"
            result = _err("VALIDATION_ERROR", "users store is not a list.")

    if result is None:
        u_exact = username.strip() if isinstance(username, str) else None
        e_exact = entity.strip() if isinstance(entity, str) else None

        filtered = []
        for u in users:
            if not isinstance(u, dict):
                continue
            if u_exact is not None and u.get("username") != u_exact:
                continue
            if e_exact is not None and u.get("entity") != e_exact:
                continue
            if cs is not None or cu is not None:
                created = u.get("created_at")
                if not isinstance(created, str) or not created.strip():
                    continue
                dt, err = _parse_dt(created)
                if err:
                    continue
                if cs is not None and dt < cs:
                    continue
                if cu is not None and dt > cu:
                    continue
            filtered.append(u)

        sb = sort_by or "created_at"
        so = sort_order or "desc"

        def _key(row):
            v = row.get(sb)
            if sb == "created_at":
                dt, err = _parse_dt(v) if isinstance(v, str) else (None, "bad")
                return dt or datetime.datetime.min
            return (v or "")

        filtered.sort(key=_key, reverse=(so == "desc"))

        # Cursor is an opaque token derived from last seen user_id in this listing
        start = 0
        if cursor is not None:
            # Accept cursor as either a raw user_id or "u_<hash>"
            cur = cursor.strip()
            if not cur:
                status = "error"
                result = _err("VALIDATION_ERROR", "cursor must not be blank when provided.")
            else:
                # Find position by matching user_id, else try hash match
                idx = None
                for i, row in enumerate(filtered):
                    uid = row.get("user_id")
                    if isinstance(uid, str) and uid == cur:
                        idx = i
                        break
                if idx is None and cur.startswith("u_"):
                    for i, row in enumerate(filtered):
                        uid = row.get("user_id")
                        if isinstance(uid, str):
                            h = hashlib.sha1(uid.encode("utf-8")).hexdigest()[:8]
                            if cur == f"u_{h}":
                                idx = i
                                break
                if idx is None:
                    status = "error"
                    result = _err("VALIDATION_ERROR", "Invalid cursor.")
                else:
                    start = idx + 1

        if result is None:
            lim = limit if limit is not None else 100
            page = filtered[start:start + lim]
            has_more = start + lim < len(filtered)
            next_cursor = None
            if has_more and page:
                last_uid = page[-1].get("user_id")
                if isinstance(last_uid, str) and last_uid:
                    next_cursor = f"u_{hashlib.sha1(last_uid.encode('utf-8')).hexdigest()[:8]}"
            result = {
                "object": "list",
                "data": page,
                "total": len(filtered),
                "limit": lim,
                "has_more": has_more,
                "next_cursor": next_cursor,
            }

    calls = _load("service_calls.json")
    if not isinstance(calls, list):
        calls = []
    calls.append({
        "id": f"call_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "timestamp": datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "status": status,
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("service_calls.json", calls)

    return result

