    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0391000" if __import__("os").path.isdir("./environment_mix/0391000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(f"{field} must be a non-empty RFC3339 date-time string.")
        ss = s.strip()
        # accept trailing Z
        if ss.endswith("Z"):
            ss2 = ss[:-1] + "+00:00"
        else:
            ss2 = ss
        return datetime.datetime.fromisoformat(ss2)

    def _enc_cursor(i):
        raw = f"i:{i}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dec_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            raise ValueError("cursor must be a non-empty string.")
        cc = c.strip()
        pad = "=" * ((4 - (len(cc) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cc + pad).encode("ascii")).decode("utf-8")
        except Exception:
            raise ValueError("Invalid cursor.")
        if not raw.startswith("i:"):
            raise ValueError("Invalid cursor.")
        try:
            i = int(raw.split(":", 1)[1])
        except Exception:
            raise ValueError("Invalid cursor.")
        if i < 0:
            raise ValueError("Invalid cursor.")
        return i

