    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0391000" if __import__("os").path.isdir("./environment_mix/0391000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_trace"
    status_out = "success"

    if trace_id is None or not isinstance(trace_id, str) or not trace_id.strip():
        status_out = "error"
        result = _err("VALIDATION_ERROR", "trace_id is required and must be a non-empty string.", trace_id=trace_id)
    else:
        tid = trace_id.strip()
        try:
            uuid.UUID(tid)
        except ValueError:
            status_out = "error"
            result = _err("VALIDATION_ERROR", "trace_id must be a valid UUID.", trace_id=trace_id)

    if status_out == "success":
        traces = _load("traces.json")
        if isinstance(traces, dict) and "rows" in traces:
            traces = traces.get("rows", [])
        if not isinstance(traces, list):
            status_out = "error"
            result = _err("VALIDATION_ERROR", "traces store is not a list.")
        else:
            found = None
            for tr in traces:
                if isinstance(tr, dict) and tr.get("trace_id") == tid:
                    found = tr
                    break
            if found is None:
                status_out = "error"
                result = _err("NOT_FOUND", "Trace not found.", trace_id=trace_id)
            else:
                # Project access: if project exists, allow; otherwise treat as unauthorized
                pn = found.get("project_name")
                if isinstance(pn, str) and pn:
                    projects = _load("projects.json")
                    if isinstance(projects, dict) and "rows" in projects:
                        projects = projects.get("rows", [])
                    if isinstance(projects, list) and projects:
                        if not any(isinstance(p, dict) and p.get("name") == pn for p in projects):
                            status_out = "error"
                            result = _err("UNAUTHORIZED", "Trace belongs to an inaccessible project.", project_name=pn)
                        else:
                            result = found
                    else:
                        result = found
                else:
                    result = found

    calls = _load("service_calls.json")
    if not isinstance(calls, list):
        calls = []
    calls.append({
        "id": f"call_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "timestamp": datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "status": status_out,
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("service_calls.json", calls)

    return result
